#include <iostream>
#include <vector>
#include <map>
#include <cassert>
#include <cstdint>
using namespace std;

constexpr int MOD = 1000000007;

class Modular {
public:
    int value;

    Modular(long long v = 0) {
        v %= MOD;
        if (v < 0) v += MOD;
        value = static_cast<int>(v);
    }

    static int mod_inverse(int a, int m = MOD) {
        int g = m, r = a, x = 0, y = 1;
        while (r != 0) {
            int q = g / r;
            g %= r; swap(g, r);
            x -= q * y; swap(x, y);
        }
        return x < 0 ? x + m : x;
    }

    explicit operator int() const { return value; }

    Modular& operator+=(const Modular& other) {
        value += other.value;
        if (value >= MOD) value -= MOD;
        return *this;
    }

    Modular& operator-=(const Modular& other) {
        value -= other.value;
        if (value < 0) value += MOD;
        return *this;
    }

    static unsigned fast_mod(uint64_t x, unsigned m = MOD) {
        return static_cast<unsigned>(x % m);
    }

    Modular& operator*=(const Modular& other) {
        value = fast_mod(static_cast<uint64_t>(value) * other.value);
        return *this;
    }

    Modular& operator/=(const Modular& other) {
        return *this *= other.mod_inverse();
    }

    friend Modular operator+(const Modular& a, const Modular& b) { return Modular(a) += b; }
    friend Modular operator-(const Modular& a, const Modular& b) { return Modular(a) -= b; }
    friend Modular operator*(const Modular& a, const Modular& b) { return Modular(a) *= b; }
    friend Modular operator/(const Modular& a, const Modular& b) { return Modular(a) /= b; }

    Modular& operator++() {
        value = (value == MOD - 1) ? 0 : value + 1;
        return *this;
    }

    Modular& operator--() {
        value = (value == 0) ? MOD - 1 : value - 1;
        return *this;
    }

    Modular operator++(int) { Modular tmp = *this; ++*this; return tmp; }
    Modular operator--(int) { Modular tmp = *this; --*this; return tmp; }

    Modular operator-() const { return value ? MOD - value : 0; }

    bool operator==(const Modular& other) const { return value == other.value; }
    bool operator!=(const Modular& other) const { return value != other.value; }

    Modular mod_inverse() const { return Modular::mod_inverse(value); }

    Modular pow(long long exp) const {
        assert(exp >= 0);
        Modular base = *this, res = 1;
        while (exp > 0) {
            if (exp & 1) res *= base;
            base *= base;
            exp >>= 1;
        }
        return res;
    }
};

const int MAX_SIZE = 7;
int size;
Modular chance[MAX_SIZE][MAX_SIZE];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> size;

    for (int i = 0; i < size; ++i) {
        for (int j = 0; j < size; ++j) {
            int p;
            cin >> p;
            chance[i][j] = Modular(p) / Modular(100);
        }
    }

    vector<vector<int>> masks_by_cardinality(MAX_SIZE + 1);
    vector<int> position_map(1 << size, -1);

    for (int mask = 0; mask < (1 << size); ++mask) {
        int cardinality = __builtin_popcount(mask);
        position_map[mask] = masks_by_cardinality[cardinality].size();
        masks_by_cardinality[cardinality].push_back(mask);
    }

    map<long long, Modular> state_map;
    state_map[1LL << position_map[0]] = Modular(1);

    for (int iteration = 0; iteration < size; ++iteration) {
        map<long long, Modular> next_state_map;

        for (int current = 0; current < (1 << size); ++current) {
            Modular product = Modular(1);
            for (int j = 0; j < size; ++j) {
                if ((current >> j) & 1) {
                    product *= chance[iteration][j];
                } else {
                    product *= (Modular(1) - chance[iteration][j]);
                }
            }

            for (const auto& [state, probability] : state_map) {
                long long current_state = state;
                Modular prob = probability;

                long long next_state = 0;

                for (int mask : masks_by_cardinality[iteration]) {
                    if ((current_state >> position_map[mask]) & 1) {
                        for (int i = 0; i < size; ++i) {
                            if (((current >> i) & 1) && !((mask >> i) & 1)) {
                                next_state |= 1LL << position_map[mask | (1 << i)];
                            }
                        }
                    }
                }

                next_state_map[next_state] += prob * product;
            }
        }

        state_map = move(next_state_map);
    }

    Modular final_answer = Modular(0);
    long long full_set = (1LL << size) - 1;

    for (const auto& [state, probability] : state_map) {
        if ((state >> position_map[full_set]) & 1) {
            final_answer += probability;
        }
    }

    cout << (int)final_answer << '\n';
    return 0;
}
